export async function createScene(engine, canvas, BABYLON) {
  console.clear();
  var scene = new BABYLON.Scene(engine);

  var camera = new BABYLON.ArcRotateCamera("camera", BABYLON.Tools.ToRadians(90), BABYLON.Tools.ToRadians(65), 10, BABYLON.Vector3.Zero(), scene);
  camera.setTarget(new BABYLON.Vector3(0, 0, 0));
  camera.alpha = -Math.PI / 2;
  camera.upperAlphaLimit = -1.42;
  camera.lowerAlphaLimit = -1.74;
  camera.beta = 1.6;
  camera.upperBetaLimit = 1.8;
  camera.lowerBetaLimit = 1.4;
  camera.radius = 10;
  camera.inertia = 0.4;
  camera.wheelDeltaPercentage = 0.3;
  camera.panningSensibility = 10000;
  camera.minZ = 0.01;
  camera.maxZ = 10000;
  camera.attachControl(canvas, true);

  var light = new BABYLON.HemisphericLight("light", new BABYLON.Vector3(0, 1, 0), scene);
  light.intensity = 0.7;

  const options = ["옵션1", "옵션2", "옵션3", "옵션4", "옵션5", "옵션6"];
  const colors = ["#FF9999", "#99CCFF", "#99FF99", "#FFFF99", "#FFCC99", "#CC99FF"];
  const sectionCount = options.length;

  const roulette = BABYLON.MeshBuilder.CreateDisc("roulette", { radius: 3, tessellation: sectionCount }, scene);

  const dynamicTexture = new BABYLON.DynamicTexture("dynamicTexture", { width: 512, height: 512 }, scene);
  const textureContext = dynamicTexture.getContext();

  textureContext.clearRect(0, 0, 512, 512);
  textureContext.save();
  textureContext.translate(0, 512);
  textureContext.scale(1, -1);

  for (let i = 0; i < sectionCount; i++) {
    textureContext.fillStyle = colors[i];
    textureContext.beginPath();
    textureContext.moveTo(256, 256);
    textureContext.arc(256, 256, 256, (i * 2 * Math.PI) / sectionCount, ((i + 1) * 2 * Math.PI) / sectionCount);
    textureContext.closePath();
    textureContext.fill();

    textureContext.fillStyle = "black";
    textureContext.font = "bold 32px Arial";
    textureContext.textAlign = "center";
    textureContext.textBaseline = "middle";

    for (let i = 0; i < sectionCount; i++) {
      let textX = 256 + 140 * Math.cos(((2 * i + 1) * Math.PI) / sectionCount);
      let textY = 256 + 140 * Math.sin(((2 * i + 1) * Math.PI) / sectionCount);

      textureContext.fillText(options[i], textX, textY);
    }
  }

  textureContext.restore();
  dynamicTexture.update();
  dynamicTexture.hasAlpha = true;

  const rouletteMaterial = new BABYLON.PBRMaterial("rouletteMaterial", scene);
  rouletteMaterial.metallic = 0;
  rouletteMaterial.unlit = true;
  rouletteMaterial.albedoTexture = dynamicTexture;
  roulette.material = rouletteMaterial;

  const arrow = BABYLON.MeshBuilder.CreateDisc("arrow", { tessellation: 3 });
  arrow.position.y = 2.75;
  arrow.position.z = -0.02;
  arrow.rotation.z = -Math.PI / 2;

  const arrowMaterial = new BABYLON.PBRMaterial("arrowMaterial", scene);
  arrowMaterial.metallic = 0;
  arrowMaterial.albedoColor = new BABYLON.Color3(0.46, 0.2, 0.03);
  arrowMaterial.unlit = true;
  arrow.material = arrowMaterial;

  let rotationSpeed = 0;
  let isSpinning = false;
  let isFinished = false;

  function highlightWinningSection(sectionIndex) {
    return new Promise((resolve) => {
      textureContext.clearRect(0, 0, 512, 512);
      textureContext.save();
      textureContext.translate(0, 512);
      textureContext.scale(1, -1);

      for (let i = 0; i < sectionCount; i++) {
        textureContext.fillStyle = colors[i];
        textureContext.beginPath();
        textureContext.moveTo(256, 256);
        textureContext.arc(256, 256, 256, (i * 2 * Math.PI) / sectionCount, ((i + 1) * 2 * Math.PI) / sectionCount);
        textureContext.closePath();
        textureContext.fill();

        if (i === sectionIndex) {
          textureContext.lineWidth = 8;
          textureContext.strokeStyle = "Red";
          textureContext.stroke();
        }

        let textX = 256 + 140 * Math.cos(((2 * i + 1) * Math.PI) / sectionCount);
        let textY = 256 + 140 * Math.sin(((2 * i + 1) * Math.PI) / sectionCount);

        textureContext.fillStyle = "black";
        textureContext.font = "bold 32px Arial";
        textureContext.textAlign = "center";
        textureContext.textBaseline = "middle";
        textureContext.fillText(options[i], textX, textY);
      }

      textureContext.restore();
      dynamicTexture.update();

      // requestAnimationFrame을 사용하여 다음 렌더링 프레임 이후 resolve
      requestAnimationFrame(() => {
        resolve();
      });
    });
  }

  async function spinRoulette() {
    if (isSpinning) return;
    isSpinning = true;

    rotationSpeed = Math.random() * 0.2 + 0.1;
    let deceleration = 0.0005;

    scene.onBeforeRenderObservable.add(async () => {
      if (isFinished) return;

      if (rotationSpeed > 0) {
        roulette.rotation.z += rotationSpeed;
        rotationSpeed -= deceleration;
      } else {
        rotationSpeed = 0;
        isSpinning = false;

        let finalAngle = (roulette.rotation.z - Math.PI / 2) % (2 * Math.PI);
        if (finalAngle < 0) finalAngle += 2 * Math.PI;

        let sectionIndex = Math.floor((finalAngle / (2 * Math.PI)) * sectionCount);

        // highlightWinningSection이 완료된 후 alert 실행
        await highlightWinningSection(sectionIndex);
        alert("당첨: " + options[sectionIndex]);
        isFinished = true;
      }
    });
  }

  var advancedTexture = BABYLON.GUI.AdvancedDynamicTexture.CreateFullscreenUI("UI");

  var button1 = BABYLON.GUI.Button.CreateSimpleButton("but1", "Click Me");
  button1.width = "150px";
  button1.height = "40px";
  button1.color = "white";
  button1.cornerRadius = 20;
  button1.background = "green";
  button1.onPointerUpObservable.add(function () {
    spinRoulette();
    button1.isVisible = false;
  });
  advancedTexture.addControl(button1);

  return scene;
}
